{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_def",
      "facet": "term",
      "statement": "A data structure is defined as an organization of information, usually in memory, for better algorithm efficiency.",
      "start_line": 4,
      "end_line": 7
    },
    {
      "key": "obs_examples",
      "facet": "reference",
      "statement": "Examples of data structures include queue, stack, linked list, heap, dictionary, and tree.",
      "start_line": 8,
      "end_line": 19
    },
    {
      "key": "obs_conceptual",
      "facet": "property",
      "statement": "A data structure may represent a conceptual unity, such as the name and address of a person.",
      "start_line": 19,
      "end_line": 20
    },
    {
      "key": "obs_redundancy",
      "facet": "property",
      "statement": "Data structures may include redundant information, such as the length of the list or the number of nodes in a subtree.",
      "start_line": 20,
      "end_line": 26
    },
    {
      "key": "obs_specializations",
      "facet": "relation",
      "statement": "Specializations of data structures include external memory, concurrent, passive, active, persistent, recursive, and compact data structures.",
      "start_line": 27,
      "end_line": 42
    },
    {
      "key": "obs_associated_algos",
      "facet": "relation",
      "statement": "Most data structures have associated algorithms to perform operations, such as search, insert, or balance, that maintain the properties of the data structure.",
      "start_line": 46,
      "end_line": 47
    },
    {
      "key": "obs_ref_source",
      "facet": "reference",
      "statement": "The entry is from the Dictionary of Algorithms and Data Structures, edited by Paul E. Black.",
      "start_line": 50,
      "end_line": 52
    }
  ],
  "claims": [],
  "questions": []
}
